const std::size_t n_faces = tree.number_of_faces();
    if (n_faces == 0) return false;

    int inside_count = 0;
    for (int i = 0; i < numberOfChecks; ++i) {
        // Generate random direction (unit vector)
        Point3d dir(
            std::rand() / static_cast<double>(RAND_MAX) * 2.0 - 1.0,
            std::rand() / static_cast<double>(RAND_MAX) * 2.0 - 1.0,
            std::rand() / static_cast<double>(RAND_MAX) * 2.0 - 1.0
        );
        dir = dir / std::sqrt(dir.squared_length());

        // Ray origin is point + small offset in random direction
        Point3d origin = p + dir * 1e-6;

        // Ray casting
        bool is_inside = false;
        std::size_t count = 0;
        tree.intersect_with_ray(
            origin, dir,
            [&](const Face_handle& f, const Ray_intersection_event& e) {
                is_inside = !is_inside;
                ++count;
                return count < 2; // Early exit if we have enough intersections
            }
        );

        if (is_inside) {
            ++inside_count;
        }
    }

    // If more than half of the checks say inside, consider it inside
    return inside_count > numberOfChecks / 2;
// END_CODE

